foreach($stateName in @('MERGE_HEAD','CHERRY_PICK_HEAD','REVERT_HEAD')){ $statePath=git rev-parse --git-path $stateName; Write-Output ($stateName+'='+ (Test-Path -LiteralPath $statePath)) }
exit 0",shell:"C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe",max_output_tokens:2000}));

